import { test } from 'node:test';
import assert from 'node:assert/strict';
import { exportNames, handleExport } from '../src/server.js';

// CONTRIBUTING.md, "書き出しを見せてよい相手": the holiday calendar is the only
// export a guest may see. This walks every registered export, so an export
// that forgets `requireRole(req, STAFF)` (#14, #15) fails here. When an export
// is added, it is closed to guests unless it is listed below on purpose.
const GUEST_MAY_SEE = ['holidays'];

for (const name of exportNames()) {
  const guestStatus = GUEST_MAY_SEE.includes(name) ? 200 : 403;

  test(`a guest gets ${guestStatus} for the ${name} export`, () => {
    assert.equal(handleExport(name, { role: 'guest' }).status, guestStatus);
  });

  for (const role of ['admin', 'member']) {
    test(`role ${role} downloads the ${name} export`, () => {
      assert.equal(handleExport(name, { role }).status, 200);
    });
  }
}
EOF
